          "stageDirection": "Imitant le salut empressé du jeune homme.; Prenant l’air rechigné du vieux mari.; Reprenant l’air du jeune homme.; Puis l’air du vieux mari.; Imitant les mines souriantes de la dame.; Le jeune homme, à ce moment, tire de sa poche un billet qu’il fait voir à la dame.; Pendant le troisième couplet, le mari, la femme et le galant font tous les trois, très lentement, un petit tour sur la place, le jeune homme cherchant à remettre son billet doux à la dame ; puis le jeune homme d’une main, montre quelque chose en l’air au vieux monsieur, et, de l’autre main, passe le billet à la jeune dame.",
          "stageDirectionTranslation": "Imitating the eager bow of the young man; Taking on the sour air of the old husband; Resuming the air of the young man; Then the air of the old husband; Imitating the smiling looks of the lady; The young man, at this moment, draws from his pocket a note that he shows to the lady; During the third stanza, the husband, wife and gallant all three make, very slowly, a little turn on the square, the young man seeking to deliver his love note to the lady; then the young man with one hand shows something in the air to the old gentleman, and with the other hand passes the note to the young lady."
