              "id": "a1_s9_c2_l1",
              "original": "J’ai d’abord trouvé trois cents femmes, criant, hurlant, gesticulant, faisant un tapage à ne pas entendre Dieu tonner… D’un côté, il y en avait une, les quatre fers en l’air, qui criait : « Confession ! confession !… je suis morte… » Elle avait sur la figure un X qu’on venait de lui marquer en deux coups de couteau… En face de la blessée j’ai vu…",
