          "stageDirection": "À José; En ce moment, cinq ou six femmes, à droite, réussissent à forcer la ligne des factionnaires et se précipitent sur la scène en criant : « Oui, oui, c’est elle !… » Une de ces femmes se trouve près de Carmen : celle-ci lève la main et veut se jeter sur la femme ; José arrête Carmen. Les soldats écartent les femmes et les repoussent, cette fois, tout à fait hors de la scène. Quelques sentinelles continuent à rester en vue, gardant les abords de la place.) — (S’adressant à Carmen.; Aux soldats.; Moment de silence pendant lequel Carmen se remet à fredonner de la façon la plus impertinente en regardant l’officier.",
          "stageDirectionTranslation": "To José; At this moment, five or six women on the right succeed in forcing the sentries' cordon and rush onto the stage crying: 'Yes, yes, it is she!...' One of these women is near Carmen: Carmen raises her hand and tries to throw herself upon the woman; José stops Carmen. The soldiers move the women away and push them this time completely off stage. A few sentries remain in sight, guarding the approaches to the square. Addressing Carmen; To the soldiers; Moment of silence during which Carmen resumes humming in the most impertinent fashion while looking at the officer."
