              "original": "Eh ! oui, tu m’aimes… ne me dis pas non, je m’y connais !… tes regards, la façon dont tu me parles… Et cette fleur que tu as gardée… oh ! tu peux la jeter maintenant… cela n’y fera rien : elle est restée assez de temps sur ton cœur ; le charme a opéré…",
